usage:
package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Uploads.New(
		context.TODO(),
		openai.UploadNewParams{
			Filename: "string",
			Purpose: openai.CreateUploadRequestPurposeAssistants,
			Bytes: 1,
			MimeType: "string",
			ExpiresAfter: openai.FileExpirationAfter{Anchor: "created_at", Seconds: 1},
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
